using System.Collections.Generic;
using System.Text;

namespace Acme.Export;

public sealed class CsvWriter
{
    public string Write(IReadOnlyList<Order> orders)
    {
        var csv = "";
        foreach (var order in orders)
        {
            csv += order.Id + "," + order.Customer + "," + order.Total + "\n";
        }
        return csv;
    }
}

