private static readonly char[] Special = { ',', '"', '\n' };

public string Write(IReadOnlyList<Order> orders)
{
    var builder = new StringBuilder();
    foreach (var order in orders)
    {
        builder.Append(order.Id.ToString(CultureInfo.InvariantCulture)).Append(',')
            .Append(Quote(order.Customer)).Append(',')
            .Append(order.Total.ToString("0.00", CultureInfo.InvariantCulture))
            .Append("\n");
    }
    return builder.ToString();
}

private static string Quote(string field)
{
    if (field.IndexOfAny(Special) < 0)
    {
        return field;
    }
    return string.Concat("\"", field.Replace("\"", "\"\""), "\"");
}
